"""Box projection into measured stock trim strips. No stock pixels are shipped."""
import math
from collections import defaultdict
from itertools import product

from mathutils import Vector

TEXEL_DENSITY = 400
# Generated by art/textures/measure_trims.py; pixel rectangles use a top-left origin.
# BEGIN MEASURED STRIPS
STRIPS = {'jet_mechanical': {'source': 'jet_mechanical_AlbedoTransparency_PLACEHOLDER.png', 'sha256': 'a1d7ef09225911b872631dc70476889a9c460ee4b323bc522407d03481af5b67', 'size': [2048, 2048], 'rect': [0, 4, 2048, 492]}, 'aircraft_structure': {'source': 'aircraft_structure_b_PLACEHOLDER.png', 'sha256': 'cf91bfbd61d01805987ea2be7cda77aa35030d70c167eeb62f2ce711af44cf8b', 'size': [1024, 512], 'rect': [0, 32, 1024, 416]}}
# END MEASURED STRIPS


def project(icarus):
    for obj in icarus.all_objects:
        if obj.type != "MESH":
            continue
        faces = [f for f in obj.data.polygons if obj.data.materials[f.material_index].name in STRIPS]
        if not faces:
            continue
        uv = obj.data.uv_layers.get("UVMap") or obj.data.uv_layers.new(name="UVMap")
        obj.data.calc_loop_triangles()
        normals = defaultdict(list)
        rotation = obj.matrix_world.to_3x3()
        for tri in obj.data.loop_triangles:
            if tri.area > 1e-10:
                normals[tri.polygon_index].append((rotation @ tri.normal).normalized())
        for face in faces:
            spec = STRIPS[obj.data.materials[face.material_index].name]
            width, height = spec["size"]
            x0, y0, x1, y1 = spec["rect"]
            normal = (rotation @ face.normal).normalized()
            axis = max(range(3), key=lambda i: abs(normal[i]))
            axes = [a for a in range(3) if a != axis]
            points = [obj.matrix_world @ obj.data.vertices[i].co for i in face.vertices]
            if normals[face.index] and min(abs(n[axis]) for n in normals[face.index]) < (290 / TEXEL_DENSITY) ** 2:
                # Boolean n-gons can bend through two box planes. A diagonal box plane preserves both sides.
                candidates = [Vector(v).normalized() for v in product((-1, 0, 1), repeat=3) if any(v)]
                candidates += [normal, sum(normals[face.index], Vector()).normalized()]
                normal = max(candidates, key=lambda v: min(abs(n.dot(v)) for n in normals[face.index]))
                u = normal.orthogonal().normalized()
                v = normal.cross(u).normalized()
                points = [Vector((p.dot(u), p.dot(v), 0)) for p in points]
                axes = [0, 1]
                minimum_cosine = min(abs(n.dot(normal)) for n in normals[face.index])
                # Keep the oblique projection's smallest triangles inside the stock trim density band.
                density = max(TEXEL_DENSITY, 300 / math.sqrt(max(minimum_cosine, 1e-9)))
            else:
                density = TEXEL_DENSITY
            # Put a face's shorter box side across the strip; U repeats along its full-width strip.
            if max(p[axes[0]] for p in points) - min(p[axes[0]] for p in points) < max(
                    p[axes[1]] for p in points) - min(p[axes[1]] for p in points):
                axes.reverse()
            low = min(p[axes[1]] for p in points)
            span = max(p[axes[1]] for p in points) - low
            if span * density > y1 - y0 - 8:
                raise ValueError("trims: %s face %d is too broad for its strip at 400 px/m" % (obj.name, face.index))
            for i, p in zip(face.loop_indices, points):
                uv.data[i].uv = (p[axes[0]] * density / width,
                                 1 - (y0 + 4 + (p[axes[1]] - low) * density) / height)


def check(icarus):
    samples = []
    subpixel = 0
    counts = {name: 0 for name in STRIPS}
    for obj in icarus.all_objects:
        if obj.type != "MESH":
            continue
        mesh = obj.data
        mesh.calc_loop_triangles()
        for tri in mesh.loop_triangles:
            name = mesh.materials[tri.material_index].name
            if name not in STRIPS:
                continue
            if not mesh.uv_layers.active:
                raise ValueError("trims: missing UVs on " + obj.name)
            counts[name] += 1
            spec = STRIPS[name]
            width, height = spec["size"]
            _, y0, _, y1 = spec["rect"]
            uv = [mesh.uv_layers.active.data[i].uv for i in tri.loops]
            if any(not math.isfinite(c) for p in uv for c in p) or any(
                    not 1 - y1 / height <= p.y <= 1 - y0 / height for p in uv):
                raise ValueError("trims: UV outside measured strip on " + obj.name)
            pixels = [Vector((p.x * width, p.y * height)) for p in uv]
            area = abs((pixels[1] - pixels[0]).cross(pixels[2] - pixels[0])) / 2
            points = [obj.matrix_world @ mesh.vertices[i].co for i in tri.vertices]
            world_area = (points[1] - points[0]).cross(points[2] - points[0]).length / 2
            # A Boolean sliver smaller than one target pixel cannot give a stable UV density measurement.
            if world_area * TEXEL_DENSITY ** 2 < 1:
                subpixel += 1
            else:
                if area < 1e-10:
                    raise ValueError("trims: zero-area UV on " + obj.name)
                samples.append(math.sqrt(area / world_area))
    if not 290 <= min(samples) <= max(samples) <= 670:
        raise ValueError("trims: measured density %.3f to %.3f is outside 290 to 670 px/m" % (min(samples), max(samples)))
    return {"triangles": counts, "min_px_per_m": min(samples), "max_px_per_m": max(samples),
            "target_px_per_m": TEXEL_DENSITY, "subpixel_triangles": subpixel}
